REQUIRED_DERIVED_COUNTS = {'CalibrationBall_Center': 1, 'LLD_LeftProjection': 1, 'LLD_RightProjection': 1, 'Left_CupOpeningEllipse_Center': 1, 'Left_CupOpeningEllipse_MajorAxis': 2, 'Left_CupOpeningEllipse_MinorAxis': 2, 'Left_FemoralNeckAxis': 2, 'Left_FemoralNeckAxis_Origin': 1, 'Left_FemoralShaftAxis': 2, 'Left_FemoralShaftAxis_Origin': 1, 'Left_ImplantNeckAxis': 2, 'Left_ImplantNeckAxis_Origin': 1, 'Left_StemAlignmentAxis': 2, 'Left_StemAlignmentAxis_Origin': 1, 'Right_CupOpeningEllipse_Center': 1, 'Right_CupOpeningEllipse_MajorAxis': 2, 'Right_CupOpeningEllipse_MinorAxis': 2, 'Right_FemoralNeckAxis': 2, 'Right_FemoralNeckAxis_Origin': 1, 'Right_FemoralShaftAxis': 2, 'Right_FemoralShaftAxis_Origin': 1, 'Right_ImplantNeckAxis': 2, 'Right_ImplantNeckAxis_Origin': 1, 'Right_StemAlignmentAxis': 2, 'Right_StemAlignmentAxis_Origin': 1}


def assert_csv_coverage(path):
    with path.open(newline='', encoding='utf-8-sig') as handle:
        rows = list(csv.DictReader(handle))
    measures = {row['name']: row for row in rows if row['section'] == 'measurement'}
    missing = set(REQUIRED_MEASUREMENTS) - set(measures)
    assert not missing, f'Missing CSV measurements: {sorted(missing)}'
    measurement_counts = Counter(row['name'] for row in rows if row['section'] == 'measurement')
    for name in REQUIRED_MEASUREMENTS:
        assert measurement_counts[name] == 1, f'Duplicate CSV measurement: {name}'
        row = measures[name]
        value = row.get('raw_value') or row.get('corrected_value_mm')
        assert value and math.isfinite(float(value)), f'Undefined CSV measurement: {name}'
    roles = {row.get('role') or row['details'].split(';')[0]: row for row in rows if row['section'] in ('point', 'derived_point')}
    role_counts = Counter(row.get('role') or row['details'].split(';')[0] for row in rows if row['section'] in ('point', 'derived_point'))
    for role, count in REQUIRED_COORDINATE_COUNTS.items():
        assert role_counts[role] == count, f'Incomplete CSV point group {role}: {role_counts[role]} versus {count}'
    derived_counts = Counter(row['name'] for row in rows if row['section'] == 'derived_point' and not (row.get('role') or row['details']))
    for name, count in REQUIRED_DERIVED_COUNTS.items():
        assert derived_counts[name] == count, f'Missing analytic construction: {name}'
    for row in rows:
        if row['section'] in ('point', 'derived_point'):
            assert all(math.isfinite(float(row[key])) for key in ('x_ras', 'y_ras', 'z_ras')), 'Invalid CSV coordinate'
    required = set(REQUIRED_COORDINATE_COUNTS)
    for side in ('left', 'right'):
        for i in range(1, 5):
            row = roles[f'{side}_femoralShaftContour{i}']
            assert row['curve_type'] != '' and row['curve_points_per_segment'] != '', 'Missing contour reconstruction metadata'
    return {'required_measurements': len(REQUIRED_MEASUREMENTS), 'required_coordinate_roles': len(required), 'required_analytic_constructions': len(REQUIRED_DERIVED_COUNTS)}
